function parsePrometheus(text) {
    const result = {};
    const rawText = (typeof text === 'object' && text !== null && text.data) ? text.data : text;
    if (!rawText || typeof rawText !== 'string') return result;
    for (const line of rawText.split('\n')) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;
        const match = trimmed.match(/^([a-zA-Z_:][a-zA-Z0-9_:]*)(?:\{([^}]*)\})?\s+([\d.eE+\-]+|NaN|Inf|-Inf)/);
        if (!match) continue;
        const [, name, labelStr, valueStr] = match;
        const value = parseFloat(valueStr);
        const labels = {};
        if (labelStr) {
            const labelPattern = /([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*"([^"]*)"/g;
            let labelMatch;
            while ((labelMatch = labelPattern.exec(labelStr)) !== null) {
                labels[labelMatch[1]] = labelMatch[2];
            }
        }
        if (!result[name]) result[name] = [];
        result[name].push({ labels, value });
    }
    return result;
}

function extractAll(metrics, nodeIp) {
    const get = (name) => metrics[name] || [];
    const sum = (name) => get(name).reduce((s, m) => s + m.value, 0);
    const first = (name) => get(name)[0]?.value ?? null;
    const findLabel = (name, labelKey, labelVal) => get(name).find(m => m.labels[labelKey] === labelVal);
    const byLabel = (name, labelKey, labelVal) => get(name).filter(m => m.labels[labelKey] === labelVal);

    // Node Health Check: If no metrics returned, mark as offline
    if (Object.keys(metrics).length === 0) {
        return { 
            node_ip: nodeIp, 
            status: 'offline', 
            total_requests: 0, 
            active_streams: 0, 
            protocol: 'unknown',
            quic_connections: [] 
        };
    }

    // Parse Response Codes
    const response_codes = {};
    get('cloudflared_tunnel_response_by_code').forEach(m => {
        const code = m.labels.status_code || m.labels.code || 'unknown';
        response_codes[code] = (response_codes[code] || 0) + m.value;
    });
    const totalResp = Object.values(response_codes).reduce((s, v) => s + v, 0);
    const total2xx = Object.entries(response_codes).filter(([k]) => k.startsWith('2') || k.startsWith('3')).reduce((s, [, v]) => s + v, 0);

    // Extract Connection IDs
    const connIds = [...new Set([
        ...get('cloudflared_tunnel_total_requests').map(m => m.labels.connection_id || m.labels.connector_id).filter(Boolean),
        ...get('cloudflared_tunnel_active_streams').map(m => m.labels.connection_id || m.labels.connector_id).filter(Boolean),
        ...get('cloudflared_tunnel_server_locations').map(m => m.labels.connection_id).filter(Boolean)
    ])];

    // QUIC specific data extraction
    const connIndexSet = new Set();
    Object.keys(metrics).filter(k => k.startsWith('quic_client_')).forEach(k => {
        get(k).forEach(m => { 
            const idx = m.labels.conn_index ?? m.labels.connection_id;
            if (idx != null) connIndexSet.add(idx); 
        });
    });

    const quic_connections = [...connIndexSet].sort().map(idx => {
        const findQuic = (name) => get(name).find(m => m.labels.conn_index === idx || m.labels.connection_id === idx)?.value ?? null;
        const lostPkts = get('quic_client_lost_packets')
            .filter(m => m.labels.conn_index === idx || m.labels.connection_id === idx)
            .map(m => ({ reason: m.labels.reason, count: m.value }));
        const locEntry = findLabel('cloudflared_tunnel_server_locations', 'connection_id', idx);
        const edge_location = locEntry ? locEntry.labels.edge_location : null;

        return {
            conn_index: idx,
            edge_location,
            latest_rtt:        findQuic('quic_client_latest_rtt'),
            min_rtt:           findQuic('quic_client_min_rtt'),
            smoothed_rtt:      findQuic('quic_client_smoothed_rtt'),
            congestion_state:  findQuic('quic_client_congestion_state'),
            congestion_window: findQuic('quic_client_congestion_window'),
            sent_bytes:        findQuic('quic_client_sent_bytes'),
            receive_bytes:     findQuic('quic_client_receive_bytes'),
            lost_packets:      lostPkts,
        };
    });

    // Determine current protocol
    const protocolEntry = get('cloudflared_tunnel_protocol')[0];
    const protocol = protocolEntry ? protocolEntry.labels.protocol : (quic_connections.length > 0 ? 'quic' : 'http2');

    // Build Info
    const build = get('build_info')[0]?.labels || {};

    // RPC Operations
    const rpcMethodSet = new Set(get('cloudflared_rpc_client_operations').map(m => m.labels.method));
    const rpc_operations = [...rpcMethodSet].map(method => {
        const ops      = byLabel('cloudflared_rpc_client_operations', 'method', method).reduce((s, m) => s + m.value, 0);
        const failures = byLabel('cloudflared_rpc_client_failures',   'method', method).reduce((s, m) => s + m.value, 0);
        const latSum   = byLabel('cloudflared_rpc_client_latency_secs_sum',   'method', method).reduce((s, m) => s + m.value, 0);
        const latCount = byLabel('cloudflared_rpc_client_latency_secs_count', 'method', method).reduce((s, m) => s + m.value, 0);
        return {
            method,
            count:       ops,
            failures,
            latency_avg: latCount > 0 ? latSum / latCount : null,
        };
    });

    // Memory and GC Metrics
    const gcP50 = get('go_gc_duration_seconds').find(m => m.labels.quantile === '0.5')?.value ?? null;
    const gcCount = get('go_gc_duration_seconds_count')[0]?.value ?? null;

    return {
        node_ip:              nodeIp,
        status:               'online',
        protocol:             protocol,
        version:              build.version,
        goversion:            build.goversion,
        connection_ids:       connIds, 
        total_requests:       Math.round(sum('cloudflared_tunnel_total_requests')),
        active_streams:       Math.round(first('cloudflared_tunnel_concurrent_requests_per_tunnel') ?? 0),
        ha_connections:       first('cloudflared_tunnel_ha_connections'),
        concurrent_requests:  first('cloudflared_tunnel_concurrent_requests_per_tunnel'),
        request_errors:       Math.round(sum('cloudflared_tunnel_request_errors')),
        tcp_total_sessions:   Math.round(sum('cloudflared_tcp_total_sessions')),
        tcp_active_sessions:  first('cloudflared_tcp_active_sessions'),
        config_pushes:        Math.round(sum('cloudflared_config_local_config_pushes')),
        config_push_errors:   Math.round(sum('cloudflared_config_local_config_pushes_errors')),
        register_success:     Math.round(sum('cloudflared_tunnel_tunnel_register_success')),
        response_codes,
        success_rate:         totalResp > 0 ? parseFloat(((total2xx / totalResp) * 100).toFixed(2)) : null,
        quic_connections,
        quic_total_connections: first('quic_client_total_connections'),
        quic_closed_connections: first('quic_client_closed_connections'),
        server_locations:     get('cloudflared_tunnel_server_locations').filter(m => m.value === 1).map(m => ({ id: m.labels.connection_id, loc: m.labels.edge_location })),
        rpc_operations,
        goroutines:           first('go_goroutines'),
        threads:              first('go_threads'),
        gc_count:             gcCount != null ? Math.round(gcCount) : null,
        gc_pause_ms:          gcP50 != null ? gcP50 * 1000 : null,
        heap_alloc_bytes:     first('go_memstats_alloc_bytes'),
        heap_inuse_bytes:     first('go_memstats_heap_inuse_bytes'),
        heap_sys_bytes:       first('go_memstats_heap_sys_bytes'),
        resident_memory_bytes: first('process_resident_memory_bytes'),
        virtual_memory_bytes: first('process_virtual_memory_bytes'),
        cpu_seconds_total:    first('process_cpu_seconds_total'),
        open_fds:             first('process_open_fds'),
        max_fds:              first('process_max_fds'),
        network_rx_bytes:     first('process_network_receive_bytes_total'),
        network_tx_bytes:     first('process_network_transmit_bytes_total'),
        process_start_time:   first('process_start_time_seconds'),
        gomaxprocs:           first('go_sched_gomaxprocs_threads'),
        raw_metric_count:     Object.keys(metrics).length,
    };
}

let n1Raw = null, n2Raw = null, n3Raw = null;
try { n1Raw = $('Scrape Node 1 Metrics').first()?.json || null; } catch(e) {}
try { n2Raw = $('Scrape Node 2 Metrics').first()?.json || null; } catch(e) {}
try { n3Raw = $('Scrape Node 3 Metrics').first()?.json || null; } catch(e) {}

const t1 = typeof n1Raw === 'string' ? n1Raw : (n1Raw?.data || JSON.stringify(n1Raw || {}));
const t2 = typeof n2Raw === 'string' ? n2Raw : (n2Raw?.data || JSON.stringify(n2Raw || {}));
const t3 = typeof n3Raw === 'string' ? n3Raw : (n3Raw?.data || JSON.stringify(n3Raw || {}));

const node1 = extractAll(parsePrometheus(t1), '192.168.30.67');
const node2 = extractAll(parsePrometheus(t2), '192.168.30.68');
const node3 = extractAll(parsePrometheus(t3), '192.168.30.69');

const totalReqs = (node1.total_requests || 0) + (node2.total_requests || 0) + (node3.total_requests || 0);

const n1pct = totalReqs > 0 ? Math.round(((node1.total_requests || 0) / totalReqs) * 100) : 0;
const n2pct = totalReqs > 0 ? Math.round(((node2.total_requests || 0) / totalReqs) * 100) : 0;
const n3pct = totalReqs > 0 ? Math.max(0, 100 - (n1pct + n2pct)) : 0;

return [{
    json: {
        nodes: [
            { ...node1, load_pct: n1pct },
            { ...node2, load_pct: n2pct },
            { ...node3, load_pct: n3pct },
        ],
        total_requests:       totalReqs,
        total_active_streams: (node1.active_streams || 0) + (node2.active_streams || 0) + (node3.active_streams || 0),
        load_balance: {
            node1_ip:    '192.168.30.67',
            node1_pct:   n1pct,
            node2_ip:    '192.168.30.68',
            node2_pct:   n2pct,
            node3_ip:    '192.168.30.69',
            node3_pct:   n3pct,
            is_balanced: totalReqs === 0 || (Math.abs(n1pct - 33) <= 25 && Math.abs(n2pct - 33) <= 25),
        },
        scraped_at: new Date().toISOString(),
    }
}];

const INTERNAL_IPS = new Set(['185.153.179.155','86.104.23.172','192.168.30.1','192.168.30.67','192.168.30.68','192.168.30.69']);
const INTERNAL_UAS = ['nginx-ssl early hints','bastion early hints'];
const CRAWLER_UAS = ['python-requests','python-urllib','go-http-client','curl/','wget/','httpx','httpie','libwww','nmap','nikto','masscan','zgrab','nuclei','scrapy','crawler','spider','bot/','dataprovider','semrushbot','ahrefsbot','mj12bot','dotbot','petalbot','wpscanner','sqlmap'];
const PROBE_PATHS = ['/.env','/.git','/wp-admin','/wp-login','/phpmyadmin','/admin','/config','/.well-known/security','/actuator','/manager/html','/cgi-bin','/xmlrpc.php','/api/v1/auth','/console','/setup.php','/install','/.DS_Store','/etc/passwd','/proc/self','/vendor/','/composer','/package.json','/server-status','/.aws/','/backup','/db/','/database','/sql','/dump','/telescope','/horizon','/api-docs','/swagger'];
const AUTH_PATHS = ['/login','/auth','/token','/signin','/api/auth','/wp-login','/admin','/user/login','/account/login'];

function classify(d) {
    const ua   = (d.userAgent || '').toLowerCase();
    const path = (d.clientRequestPath || '').toLowerCase();
    const st   = d.edgeResponseStatus || 0;
    const isCrawlerUa  = CRAWLER_UAS.some(s => ua.includes(s));
    const isProbePath  = PROBE_PATHS.some(p => path.startsWith(p) || path.includes(p));
    const isAuthPath   = AUTH_PATHS.some(p => path.includes(p));
    const isAuthError  = st === 401 || st === 403;
    if (isCrawlerUa && isProbePath)        return 'crawler-probe';
    if (isAuthPath && isAuthError)         return 'brute-force';
    if (isProbePath)                       return 'probe';
    if (isCrawlerUa)                       return 'crawler';
    return 'anomaly';
}

const gqlRaw = $('Fetch Error Analytics').first()?.json || null;
const raw = (gqlRaw?.data?.viewer?.zones?.[0]?.httpRequestsAdaptiveGroups || [])
    .filter(entry => {
        if (INTERNAL_IPS.has(entry.dimensions?.clientIP || '')) return false;
        const ua = (entry.dimensions?.userAgent || '').toLowerCase();
        if (INTERNAL_UAS.some(s => ua.includes(s.toLowerCase()))) return false;
        return true;
    });

const enriched = raw.map(entry => {
    const d = entry.dimensions || {};
    const threat_class = classify(d);
    const severity = (threat_class === 'scanner' || threat_class === 'brute-force') ? 'high'
        : (threat_class === 'probe' || threat_class === 'crawler-probe') ? 'medium' : 'low';
    return {
        count: entry.count,
        ip:      d.clientIP || '',
        country: d.clientCountryName || '',
        host:    d.clientRequestHTTPHost || '',
        path:    d.clientRequestPath || '',
        method:  d.clientRequestHTTPMethodName || '',
        ua:      d.userAgent || '',
        status:  d.edgeResponseStatus || 0,
        bucket:  d.datetimeFiveMinutes || null,
        threat_class,
        severity
    };
});

const byIp = {};
enriched.forEach(e => {
    if (!byIp[e.ip]) byIp[e.ip] = { ip: e.ip, country: e.country, total: 0, classes: new Set(), paths: new Set(), uas: new Set(), severity: 'low' };
    byIp[e.ip].total += e.count;
    byIp[e.ip].classes.add(e.threat_class);
    byIp[e.ip].paths.add(e.path);
    if (e.ua) byIp[e.ip].uas.add(e.ua);
    if (e.severity === 'high') byIp[e.ip].severity = 'high';
    else if (e.severity === 'medium' && byIp[e.ip].severity !== 'high') byIp[e.ip].severity = 'medium';
});

const INTERNAL_PATH_PREFIXES = ['/healthz','/rest/','/webhook/','/types/','/workflows/','/status/','/assets/'];
const waf_candidates = Object.values(byIp)
    .filter(e => {
        if (e.severity !== 'high' && e.total < 10) return false;
        const allInternal = [...e.paths].every(p => INTERNAL_PATH_PREFIXES.some(pfx => p.startsWith(pfx)));
        return !allInternal;
    })
    .sort((a, b) => b.total - a.total)
    .slice(0, 20)
    .map(e => ({
        ip:             e.ip,
        country:        e.country,
        total_hits:     e.total,
        threat_classes: [...e.classes],
        severity:       e.severity,
        sample_paths:   [...e.paths].slice(0, 5),
        sample_uas:     [...e.uas].slice(0, 2),
        waf_rule:       `(ip.src eq ${e.ip})`,
        waf_action:     e.severity === 'high' ? 'block' : 'challenge'
    }));

const threat_summary = {
    total:        enriched.reduce((s, e) => s + e.count, 0),
    unique_ips:   Object.keys(byIp).length,
    scanners:     enriched.filter(e => e.threat_class === 'scanner').reduce((s,e) => s + e.count, 0),
    probes:       enriched.filter(e => e.threat_class === 'probe' || e.threat_class === 'crawler-probe').reduce((s,e) => s + e.count, 0),
    crawlers:     enriched.filter(e => e.threat_class === 'crawler').reduce((s,e) => s + e.count, 0),
    brute_force:  enriched.filter(e => e.threat_class === 'brute-force').reduce((s,e) => s + e.count, 0),
    anomalies:    enriched.filter(e => e.threat_class === 'anomaly').reduce((s,e) => s + e.count, 0),
    high_severity: waf_candidates.filter(e => e.severity === 'high').length
};

const ip_activity = Object.values(byIp).map(e => ({
    ip:             e.ip,
    country:        e.country,
    total_hits:     e.total,
    threat_classes: [...e.classes],
    severity:       e.severity,
    sample_paths:   [...e.paths].slice(0, 10),
    sample_uas:     [...e.uas].slice(0, 3)
}));

return [{ json: { threat_log: enriched, threat_summary, waf_candidates, ip_activity } }];

const Redis = require('ioredis');

const REDIS_CONFIG = {
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 2000,
    maxRetriesPerRequest: 1
};

let tunnels = [];
try {
    tunnels = $('Merge Data').all().map(item => item.json);
} catch (e) {}

let metricsData = {};
try {
    metricsData = $('Parse Prometheus Metrics').first()?.json || {};
} catch (e) {
    console.error("Metrics data unavailable:", e.message);
}

let threatData = {};
try {
    threatData = $('Classify Threats').first()?.json || {};
} catch (e) {
    console.error("Threat data unavailable:", e.message);
}

const totalConnectors = tunnels.reduce((s, t) => s + (t.connector_count || 0), 0);

const total_rx = (metricsData.nodes || []).reduce((s,n) => s + (n.network_rx_bytes || 0), 0);
const total_tx = (metricsData.nodes || []).reduce((s,n) => s + (n.network_tx_bytes || 0), 0);
const total_errs = (metricsData.nodes || []).reduce((s,n) => s + (n.request_errors || 0), 0);

const total_response_codes = (metricsData.nodes || []).reduce((agg, n) => {
    Object.entries(n.response_codes || {}).forEach(([k, v]) => {
        agg[k] = (agg[k] || 0) + v;
    });
    return agg;
}, {});

const enrichedTunnels = tunnels.map(tunnel => ({
    ...tunnel,
    connectors: (tunnel.connectors || []).map((connector, index) => {
        let matchingNode = (metricsData.nodes || []).find(n =>
            (n.connection_ids || []).includes(connector.client_id) ||
            (n.connection_ids || []).includes(connector.id)
        );

        if (!matchingNode && metricsData.nodes && metricsData.nodes[index]) {
            matchingNode = metricsData.nodes[index];
        }

        return {
            ...connector,
            metrics: matchingNode ? {
                node_ip: matchingNode.node_ip,
                total_requests: matchingNode.total_requests,
                active_streams: matchingNode.active_streams,
                load_pct: matchingNode.load_pct,
                success_rate: matchingNode.success_rate,
                response_codes: matchingNode.response_codes
            } : null
        };
    })
}));

const payload = {
    summary: {
        total_tunnels: tunnels.length,
        healthy: tunnels.filter(t => t.status === 'healthy').length,
        degraded: tunnels.filter(t => t.status === 'degraded').length,
        down: tunnels.filter(t => t.status === 'inactive').length,
        total_connectors: totalConnectors,
        total_requests: metricsData.total_requests || 0,
        total_active_streams: metricsData.total_active_streams || 0,
        total_rx_bytes: total_rx,
        total_tx_bytes: total_tx,
        total_proxy_errors: total_errs
    },
    tunnels: enrichedTunnels,
    load_balance: metricsData.load_balance || null,
    nodes: metricsData.nodes || [],
    error_analytics: (() => { try { const g = $('Fetch Error Analytics').first()?.json; return g?.data?.viewer?.zones?.[0]?.httpRequestsAdaptiveGroups || []; } catch(e) { return []; } })(),
    threat_log: threatData.threat_log || [],
    threat_summary: threatData.threat_summary || null,
    waf_candidates: threatData.waf_candidates || [],
    fetched_at: new Date().toISOString()
};

const redis = new Redis(REDIS_CONFIG);

return (async () => {
    try {
        await redis.set('cf:tunnel:status', JSON.stringify(payload), 'EX', 120);

        const gqlErrors = payload.error_analytics || [];
        const err503 = gqlErrors.filter(e => e.dimensions?.edgeResponseStatus === 503).reduce((s, e) => s + e.count, 0);
        const err504 = gqlErrors.filter(e => e.dimensions?.edgeResponseStatus === 504).reduce((s, e) => s + e.count, 0);
        const authentikErrors = gqlErrors
            .filter(e => (e.dimensions?.clientRequestHTTPHost || '').includes('authentik'))
            .reduce((s, e) => s + e.count, 0);
        const historyPoint = {
            time: payload.fetched_at,
            requests: payload.summary.total_requests,
            streams: payload.summary.total_active_streams,
            errors: payload.summary.total_proxy_errors,
            rx: payload.summary.total_rx_bytes,
            tx: payload.summary.total_tx_bytes,
            response_codes: total_response_codes,
            err503,
            err504,
            authentik_errors: authentikErrors
        };
        await redis.lpush('cf:tunnel:history', JSON.stringify(historyPoint));
        await redis.ltrim('cf:tunnel:history', 0, 59);

        // Persist rolling 24h threat history (720 entries at 2-min intervals)
        const threatSummary = threatData.threat_summary || null;
        if (threatSummary && threatSummary.total > 0) {
            const topOffenders = (threatData.waf_candidates || [])
                .slice(0, 10)
                .map(e => ({
                    ip:             e.ip,
                    country:        e.country,
                    total_hits:     e.total_hits,
                    threat_classes: e.threat_classes,
                    severity:       e.severity,
                    sample_paths:   e.sample_paths
                }));

            const threatHistoryPoint = {
                time:          payload.fetched_at,
                summary:       threatSummary,
                top_offenders: topOffenders
            };
            await redis.lpush('cf:tunnel:threat_history', JSON.stringify(threatHistoryPoint));
            await redis.ltrim('cf:tunnel:threat_history', 0, 719);
        }

        // Persistent threat library: accumulate per-IP records indefinitely
        const ipActivity = threatData.ip_activity || [];
        if (ipActivity.length > 0) {
            const now = Date.now();
            const pipeline = redis.pipeline();
            for (const ip of ipActivity) {
                const existingRaw = await redis.hget('cf:threat:known_ips', ip.ip);
                const rec = existingRaw ? JSON.parse(existingRaw) : {
                    first_seen:        payload.fetched_at,
                    total_hits_alltime: 0,
                    countries:         [],
                    threat_classes:    [],
                    severity_peak:     'low',
                    sample_paths:      [],
                    sample_uas:        []
                };
                rec.last_seen          = payload.fetched_at;
                rec.total_hits_alltime += ip.total_hits;
                rec.countries          = [...new Set([...rec.countries, ip.country].filter(Boolean))];
                rec.threat_classes     = [...new Set([...rec.threat_classes, ...(ip.threat_classes || [])])];
                rec.sample_paths       = [...new Set([...rec.sample_paths, ...(ip.sample_paths || [])])].slice(0, 10);
                rec.sample_uas         = [...new Set([...rec.sample_uas,   ...(ip.sample_uas   || [])])].slice(0, 5);
                if (ip.severity === 'high') rec.severity_peak = 'high';
                else if (ip.severity === 'medium' && rec.severity_peak !== 'high') rec.severity_peak = 'medium';
                pipeline.hset('cf:threat:known_ips', ip.ip, JSON.stringify(rec));
                pipeline.zadd('cf:threat:ip_timeline', now, ip.ip);
            }
            await pipeline.exec();
        }

        return [{ json: { success: true, cached_at: payload.fetched_at, tunnel_count: tunnels.length, connector_count: totalConnectors, total_requests: metricsData.total_requests || 0 } }];
    } catch(e) {
        return [{ json: { success: false, error: e.message } }];
    } finally {
        await redis.quit();
    }
})();

const Redis = require('ioredis');

const REDIS_CONFIG = {
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 2000,
    maxRetriesPerRequest: 1
};

const redis = new Redis(REDIS_CONFIG);

return (async () => {
    try {
        const raw = await redis.get('cf:tunnel:status');
        if (!raw) {
            return [{ json: { error: 'No data cached yet.', fetched_at: null, summary: null, tunnels: [] } }];
        }

        const [historyRaw, threatHistoryRaw, libraryIps, libraryData] = await Promise.all([
            redis.lrange('cf:tunnel:history', 0, -1),
            redis.lrange('cf:tunnel:threat_history', 0, -1),
            redis.zrevrange('cf:threat:ip_timeline', 0, 99),
            redis.hgetall('cf:threat:known_ips')
        ]);

        const history = historyRaw.map(h => JSON.parse(h)).reverse();
        const threat_history = threatHistoryRaw.map(h => JSON.parse(h)).reverse();

        const threat_library = libraryIps.map(ip => {
            const rec = libraryData && libraryData[ip] ? JSON.parse(libraryData[ip]) : {};
            return { ip, ...rec };
        });

        const responseData = JSON.parse(raw);
        responseData.history = history;
        responseData.threat_history = threat_history;
        responseData.threat_library = threat_library;

        return [{ json: responseData }];
    } catch(e) {
        return [{ json: { error: e.message } }];
    } finally {
        await redis.quit();
    }
})();
